from mic_chrono_part1 import make_chrono_q

questions = []

# MIC_CHRONO_009
questions.append(make_chrono_q(
    "MIC_CHRONO_009", "Chronology",
    "Arrange the following key contributions and roles of women leaders in the Constituent Assembly in correct chronological order:\n1. Sarojini Naidu and Hansa Mehta elected to the Constituent Assembly\n2. Sarojini Naidu delivers an inspirational speech supporting the Objectives Resolution\n3. Hansa Mehta presents the National Flag to the Assembly on behalf of the women of India\n4. Begum Aizaz Rasul strongly opposes separate electorates during minority debates",
    "அரசியலமைப்பு அவையில் பெண் தலைவர்களின் முக்கிய பங்களிப்புகள் மற்றும் பங்குகளை சரியான காலவரிசையில் அமைக்கவும்:\n1. சரோஜினி நாயுடு மற்றும் ஹன்சா மேத்தா அரசியலமைப்பு அவைக்குத் தேர்ந்தெடுக்கப்படுதல்\n2. குறிக்கோள்கள் தீர்மானத்தை ஆதரித்து சரோஜினி நாயுடு உத்வேக உரை ஆற்றுதல்\n3. இந்தியப் பெண்களின் சார்பில் ஹன்சா மேத்தா அவைக்கு தேசியக் கொடியை வழங்குதல்\n4. சிறுபான்மையினர் விவாதங்களின் போது பேகம் ஐசாஸ் ரசூல் தனித் தொகுதிகளைக் கடுமையாக எதிர்த்தல்",
    ["Sarojini Naidu and Hansa Mehta elected to the Constituent Assembly", "Sarojini Naidu delivers an inspirational speech supporting the Objectives Resolution", "Hansa Mehta presents the National Flag to the Assembly on behalf of the women of India", "Begum Aizaz Rasul strongly opposes separate electorates during minority debates"],
    ["சரோஜினி நாயுடு மற்றும் ஹன்சா மேத்தா அரசியலமைப்பு அவைக்குத் தேர்ந்தெடுக்கப்படுதல்", "குறிக்கோள்கள் தீர்மானத்தை ஆதரித்து சரோஜினி நாயுடு உத்வேக உரை ஆற்றுதல்", "இந்தியப் பெண்களின் சார்பில் ஹன்சா மேத்தா அவைக்கு தேசியக் கொடியை வழங்குதல்", "சிறுபான்மையினர் விவாதங்களின் போது பேகம் ஐசாஸ் ரசூல் தனித் தொகுதிகளைக் கடுமையாக எதிர்த்தல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Elected, July 1946) -> 2 (Objectives Resolution speech, Dec 1946) -> 3 (Flag presentation, Aug 14, 1947 midnight) -> 4 (Minority debate speech opposing separate electorates, Aug 1948).",
    "சரியான காலவரிசை: 1 (தேர்வு, ஜூலை 1946) -> 2 (குறிக்கோள்கள் தீர்மான உரை, டிச 1946) -> 3 (தேசியக் கொடி வழங்கல், ஆகஸ்ட் 14, 1947 நள்ளிரவு) -> 4 (தனித் தொகுதி எதிர்ப்பு உரை, ஆகஸ்ட் 1948).",
    "Correct. 1 (July 1946) -> 2 (Dec 1946) -> 3 (Aug 1947) -> 4 (Aug 1948) is exact.", "சரி. 1 (ஜூலை 1946) -> 2 (டிச 1946) -> 3 (ஆகஸ்ட் 1947) -> 4 (ஆகஸ்ட் 1948) துல்லியமானது.",
    "Incorrect. Election to Assembly (1) preceded Objectives Resolution speech (2).", "தவறு. அவைக்குத் தேர்வு (1) குறிக்கோள்கள் தீர்மான உரைக்கு முந்தியது (2).",
    "Incorrect. Objectives Resolution speech (2) preceded Flag presentation (3).", "தவறு. குறிக்கோள்கள் தீர்மான உரை (2) தேசியக் கொடி வழங்கலிற்கு முந்தியது (3).",
    "Incorrect. Election (1) preceded Flag presentation (3).", "தவறு. அவைக்குத் தேர்வு (1) தேசியக் கொடி வழங்கலிற்கு முந்தியது (3).",
    "TNPSC Trap: Hansa Mehta presented the first National Flag to free India on midnight of August 14, 1947 on behalf of Indian women.",
    "TNPSC பொறி: ஹன்சா மேத்தா ஆகஸ்ட் 14, 1947 நள்ளிரவில் இந்தியப் பெண்களின் சார்பில் சுதந்திர இந்தியாவின் முதல் தேசியக் கொடியை வழங்கினார்.",
    "Begum Aizaz Rasul was the only Muslim woman member of the Assembly and strongly advocated national integration.",
    "பேகம் ஐசாஸ் ரசூல் அவையின் ஒரே முஸ்லிம் பெண் உறுப்பினராவார்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Women's Representation", "Objectives Resolution", "National Flag adoption"]
))

# MIC_CHRONO_010
questions.append(make_chrono_q(
    "MIC_CHRONO_010", "Chronology",
    "Arrange the following major Constituent Assembly decisions and milestones in correct chronological order:\n1. First meeting of the Constituent Assembly in Constitution Hall, New Delhi\n2. Appointment of the Drafting Committee headed by Dr. B.R. Ambedkar\n3. Ratification of India's membership of the Commonwealth by Constituent Assembly\n4. Election of Dr. Rajendra Prasad as the first President of India",
    "அரசியலமைப்பு அவையின் பின்வரும் முக்கிய முடிவுகள் மற்றும் மைல்கற்களை சரியான காலவரிசையில் அமைக்கவும்:\n1. புதுடெல்லி அரசியலமைப்பு அரங்கில் அரசியலமைப்பு அவையின் முதல் கூட்டம்\n2. அம்பேத்கர் தலைமையில் வரைவுக் குழு நியமிக்கப்படுதல்\n3. காமன்வெல்த்தில் இந்தியாவின் உறுப்பினருரிமையை அரசியலமைப்பு அவை உறுதிப்படுத்துதல்\n4. டாக்டர் ராஜேந்திர பிரசாத் இந்தியாவின் முதல் குடியரசுத் தலைவராகத் தேர்ந்தெடுக்கப்படுதல்",
    ["First meeting of the Constituent Assembly in Constitution Hall, New Delhi", "Appointment of the Drafting Committee headed by Dr. B.R. Ambedkar", "Ratification of India's membership of the Commonwealth by Constituent Assembly", "Election of Dr. Rajendra Prasad as the first President of India"],
    ["புதுடெல்லி அரசியலமைப்பு அரங்கில் அரசியலமைப்பு அவையின் முதல் கூட்டம்", "அம்பேத்கர் தலைமையில் வரைவுக் குழு நியமிக்கப்படுதல்", "காமன்வெல்த்தில் இந்தியாவின் உறுப்பினருரிமையை அரசியலமைப்பு அவை உறுதிப்படுத்துதல்", "டாக்டர் ராஜேந்திர பிரசாத் இந்தியாவின் முதல் குடியரசுத் தலைவராகத் தேர்ந்தெடுக்கப்படுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (First meeting, Dec 9, 1946) -> 2 (Drafting Committee setup, Aug 29, 1947) -> 3 (Commonwealth ratification, May 1949) -> 4 (Election of 1st President, Jan 24, 1950).",
    "சரியான காலவரிசை: 1 (முதல் கூட்டம், டிச 9, 1946) -> 2 (வரைவுக் குழு அமைப்பு, ஆகஸ்ட் 29, 1947) -> 3 (காமன்வெல்த் உறுதிப்பாடு, மே 1949) -> 4 (முதல் குடியரசுத் தலைவர் தேர்வு, ஜன 24, 1950).",
    "Correct. 1 (Dec 1946) -> 2 (Aug 1947) -> 3 (May 1949) -> 4 (Jan 1950) is exact.", "சரி. 1 (டிச 1946) -> 2 (ஆகஸ்ட் 1947) -> 3 (மே 1949) -> 4 (ஜன 1950) துல்லியமானது.",
    "Incorrect. First meeting (1) occurred before Drafting Committee setup (2).", "தவறு. முதல் கூட்டம் (1) வரைவுக் குழு அமைப்பிற்கு முந்தியது (2).",
    "Incorrect. Drafting Committee setup (2) occurred before Commonwealth ratification (3).", "தவறு. வரைவுக் குழு அமைப்பு (2) காமன்வெல்த் உறுதிப்பாட்டிற்கு முந்தியது (3).",
    "Incorrect. First meeting (1) occurred before Commonwealth ratification (3).", "தவறு. முதல் கூட்டம் (1) காமன்வெல்த் உறுதிப்பாட்டிற்கு முந்தியது (3).",
    "TNPSC Trap: Commonwealth membership was ratified in May 1949 (BEFORE Constitution adoption in Nov 1949). First President elected Jan 24, 1950.",
    "TNPSC பொறி: காமன்வெல்த் உறுப்பினருரிமை மே 1949 இல் (அரசியலமைப்பு ஏற்பிற்கு முன்) உறுதிப்படுத்தப்பட்டது. முதல் குடியரசுத் தலைவர் தேர்வு ஜனவரி 24, 1950.",
    "India's Commonwealth membership was declared not to affect its sovereign republican status.",
    "இந்தியாவின் காமன்வெல்த் உறுப்பினருரிமை அதன் இறையாண்மை குடியரசு அந்தஸ்தைப் பாதிக்காது என அறிவிக்கப்பட்டது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Constituent Assembly", "Drafting Committee", "Constitutional Milestones"]
))

# MIC_CHRONO_011
questions.append(make_chrono_q(
    "MIC_CHRONO_011", "Chronology",
    "Identify the correct chronological sequence of formation of major and minor committees of the Constituent Assembly:\n1. Rules of Procedure Committee setup under Dr. Rajendra Prasad\n2. Advisory Committee on Fundamental Rights and Minorities setup under Sardar Patel\n3. Order of Business Committee setup under Dr. K.M. Munshi\n4. Drafting Committee setup under Dr. B.R. Ambedkar",
    "அரசியலமைப்பு அவையின் முக்கிய மற்றும் சிறு குழுக்கள் அமைக்கப்பட்டதன் சரியான காலவரிசையை அடையாளம் காணவும்:\n1. டாக்டர் ராஜேந்திர பிரசாத் தலைமையில் நடைமுறை விதிகள் குழு அமைக்கப்பட்டல்\n2. சர்தார் படேல் தலைமையில் அடிப்படை உரிமைகள் மற்றும் சிறுபான்மையினர் ஆலோசனைக் குழு அமைக்கப்பட்டல்\n3. டாக்டர் கே.எம். முன்ஷி தலைமையில் வணிக வரிசைக் குழு அமைக்கப்பட்டல்\n4. டாக்டர் பி.ஆர். அம்பேத்கர் தலைமையில் வரைவுக் குழு அமைக்கப்பட்டல்",
    ["Rules of Procedure Committee setup under Dr. Rajendra Prasad", "Advisory Committee on Fundamental Rights and Minorities setup under Sardar Patel", "Order of Business Committee setup under Dr. K.M. Munshi", "Drafting Committee setup under Dr. B.R. Ambedkar"],
    ["டாக்டர் ராஜேந்திர பிரசாத் தலைமையில் நடைமுறை விதிகள் குழு அமைக்கப்பட்டல்", "சர்தார் படேல் தலைமையில் அடிப்படை உரிமைகள் மற்றும் சிறுபான்மையினர் ஆலோசனைக் குழு அமைக்கப்பட்டல்", "டாக்டர் கே.எம். முன்ஷி தலைமையில் வணிக வரிசைக் குழு அமைக்கப்பட்டல்", "டாக்டர் பி.ஆர். அம்பேத்கர் தலைமையில் வரைவுக் குழு அமைக்கப்பட்டல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Rules Committee, Dec 1946) -> 2 (Advisory Committee, Jan 24, 1947) -> 3 (Order of Business Committee, Jan 25, 1947) -> 4 (Drafting Committee, Aug 29, 1947).",
    "சரியான காலவரிசை: 1 (விதிகள் குழு, டிச 1946) -> 2 (ஆலோசனைக் குழு, ஜன 24, 1947) -> 3 (வணிக வரிசைக் குழு, ஜன 25, 1947) -> 4 (வரைவுக் குழு, ஆகஸ்ட் 29, 1947).",
    "Correct. 1 (Dec 1946) -> 2 (Jan 24, 1947) -> 3 (Jan 25, 1947) -> 4 (Aug 29, 1947) is exact.", "சரி. 1 (டிச 1946) -> 2 (ஜன 24, 1947) -> 3 (ஜன 25, 1947) -> 4 (ஆகஸ்ட் 29, 1947) துல்லியமானது.",
    "Incorrect. Rules Committee (Dec 1946) was setup before Advisory Committee (Jan 1947).", "தவறு. விதிகள் குழு (டிச 1946) ஆலோசனைக் குழுவிற்கு முந்தியது (ஜன 1947).",
    "Incorrect. Advisory Committee (Jan 24) was setup before Order of Business Committee (Jan 25).", "தவறு. ஆலோசனைக் குழு (ஜன 24) வணிக வரிசைக் குழுவிற்கு முந்தியது (ஜன 25).",
    "Incorrect. Rules Committee (Dec 1946) was setup before Order of Business Committee (Jan 1947).", "தவறு. விதிகள் குழு (டிச 1946) வணிக வரிசைக் குழுவிற்கு முந்தியது (ஜன 1947).",
    "TNPSC Trap: Rules of Procedure Committee was among the first committees set up in Dec 1946. Drafting Committee was set up after Independence on Aug 29, 1947.",
    "TNPSC பொறி: நடைமுறை விதிகள் குழு டிசம்பர் 1946 இல் அமைக்கப்பட்ட முதல் குழுக்களில் ஒன்றாகும். வரைவுக் குழு சுதந்திரத்திற்குப் பின் ஆகஸ்ட் 29, 1947 இல் அமைக்கப்பட்டது.",
    "Advisory Committee headed by Patel was appointed on January 24, 1947.",
    "படேல் தலைமையிலான ஆலோசனைக் குழு ஜனவரி 24, 1947 அன்று நியமிக்கப்பட்டது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Important Committees", "Committees Formation", "Drafting Committee Formation"]
))

# MIC_CHRONO_012
questions.append(make_chrono_q(
    "MIC_CHRONO_012", "Chronology",
    "Which of the following is the correct chronological sequence of internal developments within the Drafting Committee?\n1. Appointment of original seven members of the Drafting Committee\n2. Resignation of B.L. Mitter due to ill-health and replacement by N. Madhava Rau\n3. Publication of the First Draft of the Constitution containing 315 Articles\n4. Passing away of D.P. Khaitan and replacement by T.T. Krishnamachari",
    "வரைவுக் குழுவின் உட்புற முன்னேற்றங்களின் சரியான காலவரிசை எது?\n1. வரைவுக் குழுவின் அசல் ஏழு உறுப்பினர்கள் நியமிக்கப்படுதல்\n2. உடல்நலக்குறைவால் பி.எல். மிட்டர் விலகுதல் & என். மாதவ ராவ் நியமிக்கப்படுதல்\n3. 315 சரத்துகளைக் கொண்ட அரசியலமைப்பின் முதல் வரைவு வெளியிடப்படுதல்\n4. டி.பி. கைத்தான் காலமாதல் & டி.டி. கிருஷ்ணமாச்சாரி நியமிக்கப்படுதல்",
    ["Appointment of original seven members of the Drafting Committee", "Resignation of B.L. Mitter due to ill-health and replacement by N. Madhava Rau", "Publication of the First Draft of the Constitution containing 315 Articles", "Passing away of D.P. Khaitan and replacement by T.T. Krishnamachari"],
    ["வரைவுக் குழுவின் அசல் ஏழு உறுப்பினர்கள் நியமிக்கப்படுதல்", "உடல்நலக்குறைவால் பி.எல். மிட்டர் விலகுதல் & என். மாதவ ராவ் நியமிக்கப்படுதல்", "315 சரத்துகளைக் கொண்ட அரசியலமைப்பின் முதல் வரைவு வெளியிடப்படுதல்", "டி.பி. கைத்தான் காலமாதல் & டி.டி. கிருஷ்ணமாச்சாரி நியமிக்கப்படுதல்"],
    "1 -> 2 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "2 -> 1 -> 3 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Appointment, Aug 29, 1947) -> 2 (Mitter resigned late 1947, replaced by Madhava Rau) -> 3 (First Draft published, Feb 1948) -> 4 (Khaitan died in 1948, replaced by TT Krishnamachari).",
    "சரியான காலவரிசை: 1 (நியமனம், ஆகஸ்ட் 29, 1947) -> 2 (மிட்டர் விலகல், மாதவ ராவ் சேர்க்கை, 1947 இறுதி) -> 3 (முதல் வரைவு வெளியீடு, பிப்ரவரி 1948) -> 4 (கைத்தான் மறைவு, டிடி கே சேர்க்கை, 1948).",
    "Correct. 1 (Aug 1947) -> 2 (Late 1947) -> 3 (Feb 1948) -> 4 (1948) is exact.", "சரி. 1 (ஆகஸ்ட் 1947) -> 2 (1947 இறுதி) -> 3 (பிப்ரவரி 1948) -> 4 (1948) துல்லியமானது.",
    "Incorrect. B.L. Mitter resigned (2) before First Draft publication in Feb 1948 (3).", "தவறு. பி.எல். மிட்டர் விலகல் (2) முதல் வரைவு வெளியீட்டிற்கு முந்தியது (3).",
    "Incorrect. Original members appointed (1) before Mitter resignation (2).", "தவறு. அசல் உறுப்பினர்கள் நியமனம் (1) மிட்டர் விலகலிற்கு முந்தியது (2).",
    "Incorrect. Original members appointed (1) before First Draft publication (3).", "தவறு. அசல் உறுப்பினர்கள் நியமனம் (1) முதல் வரைவு வெளியீட்டிற்கு முந்தியது (3).",
    "TNPSC Trap: B.L. Mitter resigned first (replaced by N. Madhava Rau); D.P. Khaitan died later in 1948 (replaced by T.T. Krishnamachari).",
    "TNPSC பொறி: பி.எல். மிட்டர் முதலில் விலகினார் (என். மாதவ ராவ் சேர்ந்தார்); டி.பி. கைத்தான் பின்னர் 1948 இல் மறைந்தார் (டி.டி. கிருஷ்ணமாச்சாரி சேர்ந்தார்).",
    "N. Madhava Rau was former Dewan of Mysore and T.T. Krishnamachari was a prominent businessman-politician from Madras.",
    "என். மாதவ ராவ் மைசூரின் முன்னாள் திவானாகவும், டி.டி. கிருஷ்ணமாச்சாரி தொழிலதிபர்-அரசியல்வாதியாகவும் இருந்தனர்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Drafting Committee Formation", "T. T. Krishnamachari"]
))

# MIC_CHRONO_013
questions.append(make_chrono_q(
    "MIC_CHRONO_013", "Chronology",
    "Arrange the following historical milestones in the evolution of constitutional demand in India in correct chronological order:\n1. Motilal Nehru Report drafting a proposed Constitution for India\n2. M.N. Roy putting forward the idea of a Constituent Assembly\n3. Official demand by Indian National Congress for a Constituent Assembly\n4. Jawaharlal Nehru insisting that the Constitution be framed by a Constituent Assembly elected on adult franchise",
    "இந்தியாவில் அரசியலமைப்பு கோரிக்கையின் பரிணாம வளர்ச்சியில் உள்ள பின்வரும் வரலாற்று மைல்கற்களை சரியான காலவரிசையில் அமைக்கவும்:\n1. இந்தியாவிற்கான முன்மொழியப்பட்ட அரசியலமைப்பை மோதிலால் நேரு அறிக்கை வரைதல்\n2. எம்.என். ராய் அரசியலமைப்பு நிர்ணய அவைக் கருத்தை முன்வைத்தல்\n3. இந்திய தேசிய காங்கிரஸ் அதிகாரப்பூர்வமாக அரசியலமைப்பு அவையைக் கோருதல்\n4. அரசியலமைப்பு வயதுவந்தோர் வாக்குரிமையால் தேர்ந்தெடுக்கப்பட்ட அவையால் மட்டுமே உருவாக்கப்பட வேண்டும் என ஜவகர்லால் நேரு வலியுறுத்துதல்",
    ["Motilal Nehru Report drafting a proposed Constitution for India", "M.N. Roy putting forward the idea of a Constituent Assembly", "Official demand by Indian National Congress for a Constituent Assembly", "Jawaharlal Nehru insisting that the Constitution be framed by a Constituent Assembly elected on adult franchise"],
    ["இந்தியாவிற்கான முன்மொழியப்பட்ட அரசியலமைப்பை மோதிலால் நேரு அறிக்கை வரைதல்", "எம்.என். ராய் அரசியலமைப்பு நிர்ணய அவைக் கருத்தை முன்வைத்தல்", "இந்திய தேசிய காங்கிரஸ் அதிகாரப்பூர்வமாக அரசியலமைப்பு அவையைக் கோருதல்", "அரசியலமைப்பு வயதுவந்தோர் வாக்குரிமையால் தேர்ந்தெடுக்கப்பட்ட அவையால் மட்டுமே உருவாக்கப்பட வேண்டும் என ஜவகர்லால் நேரு வலியுறுத்துதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Nehru Report, 1928) -> 2 (M.N. Roy proposal, 1934) -> 3 (INC official demand, 1935) -> 4 (Jawaharlal Nehru declaration, 1938).",
    "சரியான காலவரிசை: 1 (நேரு அறிக்கை, 1928) -> 2 (எம்.என். ராய் முன்மொழிவு, 1934) -> 3 (காங்கிரஸ் கோரிக்கை, 1935) -> 4 (ஜவகர்லால் நேரு அறிவிப்பு, 1938).",
    "Correct. 1 (1928) -> 2 (1934) -> 3 (1935) -> 4 (1938) is exact.", "சரி. 1 (1928) -> 2 (1934) -> 3 (1935) -> 4 (1938) துல்லியமானது.",
    "Incorrect. Nehru Report (1928) preceded M.N. Roy's proposal (1934).", "தவறு. நேரு அறிக்கை (1928) எம்.என். ராயின் முன்மொழிவிற்கு முந்தியது (1934).",
    "Incorrect. M.N. Roy proposal (1934) preceded INC official demand (1935).", "தவறு. எம்.என். ராய் முன்மொழிவு (1934) காங்கிரஸ் கோரிக்கைக்கு முந்தியது (1935).",
    "Incorrect. Nehru Report (1928) was the earliest among these milestones.", "தவறு. நேரு அறிக்கை (1928) இவற்றில் மிக முந்தையது.",
    "TNPSC Trap: Nehru Report (1928) was the FIRST effort by Indians to frame a written Constitution.",
    "TNPSC பொறி: 1928 நேரு அறிக்கையே இந்தியர்களால் எழுதப்பட்ட அரசியலமைப்பை உருவாக்க மேற்கொள்ளப்பட்ட முதல் முயற்சியாகும்.",
    "The 1928 Nehru Report was prepared under Motilal Nehru as a response to Lord Birkenhead's challenge.",
    "1928 நேரு அறிக்கை பிர்கன்ஹெட் பிரபுவின் சவாலுக்குப் பதிலாக மோதிலால் நேரு தலைமையில் தயாரிக்கப்பட்டது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Demand for Constituent Assembly", "Constitutional Milestones"]
))

# MIC_CHRONO_014
questions.append(make_chrono_q(
    "MIC_CHRONO_014", "Chronology",
    "Identify the correct chronological sequence of adoption of National Symbols and Emblems by the Constituent Assembly and Government of India:\n1. Adoption of the National Flag of India by Constituent Assembly\n2. Adoption of the National Anthem ('Jana Gana Mana') by Constituent Assembly\n3. Adoption of the National Song ('Vande Mataram') by Constituent Assembly\n4. Official adoption of the State Emblem of India (Sarnath Lion Capital) by Government of India",
    "அரசியலமைப்பு அவை மற்றும் இந்திய அரசாங்கத்தால் தேசிய சின்னங்கள் ஏற்றுக்கொள்ளப்பட்டதன் சரியான காலவரிசையை அடையாளம் காணவும்:\n1. அரசியலமைப்பு அவையால் இந்திய தேசியக் கொடி ஏற்றுக்கொள்ளப்படுதல்\n2. அரசியலமைப்பு அவையால் தேசிய கீதம் ('ஜன கண மன') ஏற்றுக்கொள்ளப்படுதல்\n3. அரசியலமைப்பு அவையால் தேசியப் பாடல் ('வந்தே மாதரம்') ஏற்றுக்கொள்ளப்படுதல்\n4. இந்திய அரசாங்கத்தால் இந்திய அரசு முத்திரை (சாரநாத் சிங்கத் தூண்) அதிகாரப்பூர்வமாக ஏற்றுக்கொள்ளப்படுதல்",
    ["Adoption of the National Flag of India by Constituent Assembly", "Adoption of the National Anthem ('Jana Gana Mana') by Constituent Assembly", "Adoption of the National Song ('Vande Mataram') by Constituent Assembly", "Official adoption of the State Emblem of India (Sarnath Lion Capital) by Government of India"],
    ["அரசியலமைப்பு அவையால் இந்திய தேசியக் கொடி ஏற்றுக்கொள்ளப்படுதல்", "அரசியலமைப்பு அவையால் தேசிய கீதம் ('ஜன கண மன') ஏற்றுக்கொள்ளப்படுதல்", "அரசியலமைப்பு அவையால் தேசியப் பாடல் ('வந்தே மாதரம்') ஏற்றுக்கொள்ளப்படுதல்", "இந்திய அரசாங்கத்தால் இந்திய அரசு முத்திரை (சாரநாத் சிங்கத் தூண்) அதிகாரப்பூர்வமாக ஏற்றுக்கொள்ளப்படுதல்"],
    "1 -> 2 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "2 -> 1 -> 3 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (National Flag adopted, July 22, 1947) -> 2 & 3 (National Anthem & Song adopted, Jan 24, 1950) -> 4 (State Emblem adopted on Republic Day, Jan 26, 1950).",
    "சரியான காலவரிசை: 1 (தேசியக் கொடி ஏற்பு, ஜூலை 22, 1947) -> 2 & 3 (தேசிய கீதம் & பாடல் ஏற்பு, ஜன 24, 1950) -> 4 (அரசு முத்திரை ஏற்பு, ஜன 26, 1950).",
    "Correct. 1 (July 1947) -> 2 & 3 (Jan 24, 1950) -> 4 (Jan 26, 1950) follows chronological dates.", "சரி. 1 (ஜூலை 1947) -> 2 & 3 (ஜன 24, 1950) -> 4 (ஜன 26, 1950) காலவரிசையைப் பின்பற்றுகிறது.",
    "Incorrect. Anthem & Song were adopted on same day (Jan 24, 1950).", "தவறு. கீதமும் பாடலும் ஒரே நாளில் ஏற்றுக் கொள்ளப்பட்டன (ஜன 24, 1950).",
    "Incorrect. National Flag (July 1947) was adopted before National Anthem (Jan 1950).", "தவறு. தேசியக் கொடி (ஜூலை 1947) தேசிய கீதத்திற்கு முந்தியது.",
    "Incorrect. National Flag (July 1947) was adopted before National Song (Jan 1950).", "தவறு. தேசியக் கொடி (ஜூலை 1947) தேசியப் பாடலுக்கு முந்தியது.",
    "TNPSC Trap: National Flag = July 22, 1947. Anthem & Song = Jan 24, 1950. State Emblem (Sarnath Lions) = Jan 26, 1950.",
    "TNPSC பொறி: தேசியக் கொடி = ஜூலை 22, 1947. கீதம் & பாடல் = ஜனவரி 24, 1950. அரசு முத்திரை (சாரநாத் சிங்கம்) = ஜனவரி 26, 1950.",
    "The motto 'Satyameva Jayate' inscribed below the State Emblem is taken from Mundaka Upanishad.",
    "அரசு முத்திரையின் கீழ் பொறிக்கப்பட்டுள்ள 'சத்யமேவ ஜெயதே' என்ற முழக்கம் முண்டக உபநிடதத்திலிருந்து எடுக்கப்பட்டது.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "National Flag adoption", "National Anthem adoption", "National Song", "Constitutional Facts"]
))

# MIC_CHRONO_015
questions.append(make_chrono_q(
    "MIC_CHRONO_015", "Chronology",
    "Arrange the following events relating to the strength and composition of the Constituent Assembly in correct chronological order:\n1. Cabinet Mission fixes total Assembly strength at 389 members\n2. Muslim League boycotts Assembly sessions demanding Pakistan\n3. Announcement of Mountbatten Plan partitioning British India\n4. Official publication of reduced Assembly membership of 299 members",
    "அரசியலமைப்பு அவையின் எண்ணிக்கை மற்றும் அமைப்பு தொடர்பான பின்வரும் நிகழ்வுகளை சரியான காலவரிசையில் அமைக்கவும்:\n1. கேபினட் தூதுக்குழு அவையின் மொத்த எண்ணிக்கையை 389 ஆக நிர்ணயித்தல்\n2. பாகிஸ்தான் கோரி முஸ்லீம் லீக் அவை அமர்வுகளைப் புறக்கணித்தல்\n3. பிரிட்டிஷ் இந்தியாவைப் பிரிக்கும் மவுண்ட்பேட்டன் திட்டம் அறிவிக்கப்படுதல்\n4. அவையின் குறைக்கப்பட்ட 299 உறுப்பினர்கள் எண்ணிக்கை அதிகாரப்பூர்வமாக வெளியிடப்படுதல்",
    ["Cabinet Mission fixes total Assembly strength at 389 members", "Muslim League boycotts Assembly sessions demanding Pakistan", "Announcement of Mountbatten Plan partitioning British India", "Official publication of reduced Assembly membership of 299 members"],
    ["கேபினட் தூதுக்குழு அவையின் மொத்த எண்ணிக்கையை 389 ஆக நிர்ணயித்தல்", "பாகிஸ்தான் கோரி முஸ்லீம் லீக் அவை அமர்வுகளைப் புறக்கணித்தல்", "பிரிட்டிஷ் இந்தியாவைப் பிரிக்கும் மவுண்ட்பேட்டன் திட்டம் அறிவிக்கப்படுதல்", "அவையின் குறைக்கப்பட்ட 299 உறுப்பினர்கள் எண்ணிக்கை அதிகாரப்பூர்வமாக வெளியிடப்படுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Cabinet Mission Plan, May 1946 - 389 seats) -> 2 (Muslim League boycott, Dec 1946) -> 3 (Mountbatten Plan, June 3, 1947) -> 4 (Reduced strength published, Dec 31, 1947 - 299 seats).",
    "சரியான காலவரிசை: 1 (கேபினட் திட்டம், மே 1946 - 389 இடங்கள்) -> 2 (லீக் புறக்கணிப்பு, டிச 1946) -> 3 (மவுண்ட்பேட்டன் திட்டம், ஜூன் 3, 1947) -> 4 (குறைக்கப்பட்ட எண்ணிக்கை வெளியீடு, டிச 31, 1947 - 299 இடங்கள்).",
    "Correct. 1 (May 1946) -> 2 (Dec 1946) -> 3 (June 1947) -> 4 (Dec 1947) is exact.", "சரி. 1 (மே 1946) -> 2 (டிச 1946) -> 3 (ஜூன் 1947) -> 4 (டிச 1947) துல்லியமானது.",
    "Incorrect. Cabinet Mission fixed 389 seats (1) before Muslim League boycotted (2).", "தவறு. கேபினட் திட்டம் 389 இடங்களை நிர்ணயித்தது (1).",
    "Incorrect. Muslim League boycotted in Dec 1946 (2) before Mountbatten Plan in June 1947 (3).", "தவறு. லீக் புறக்கணிப்பு டிசம்பர் 1946 இல் நடந்தது (2).",
    "Incorrect. Cabinet Mission fixed 389 seats (1) before Mountbatten Plan (3).", "தவறு. கேபினட் திட்டம் 389 இடங்களை நிர்ணயித்தது (1).",
    "TNPSC Trap: Cabinet Mission Plan (389 members) -> Partition / Mountbatten Plan (June 3, 1947) -> Reduced Strength (299 members, Dec 31, 1947).",
    "TNPSC பொறி: கேபினட் தூதுக்குழு (389 உறுப்பினர்கள்) -> மவுண்ட்பேட்டன் திட்டம் (ஜூன் 3, 1947) -> குறைக்கப்பட்ட எண்ணிக்கை (299 உறுப்பினர்கள், டிச 31, 1947).",
    "Following partition, seats for Indian Provinces fell from 292 to 229, and Princely States fell from 93 to 70.",
    "பிரிவினைக்குப் பின் மாகாண இடங்கள் 292 இலிருந்து 229 ஆகவும், சமஸ்தான இடங்கள் 93 இலிருந்து 70 ஆகவும் குறைந்தன.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Cabinet Mission Plan", "Partition impact", "Reduction from 389 to 299 members"]
))

# MIC_CHRONO_016
questions.append(make_chrono_q(
    "MIC_CHRONO_016", "Chronology",
    "Arrange the following momentous speeches delivered in the Constituent Assembly in correct chronological order:\n1. Jawaharlal Nehru moves Objectives Resolution calling for an Independent Sovereign Republic\n2. Dr. B.R. Ambedkar introduces the First Draft of the Constitution\n3. Dr. B.R. Ambedkar delivers his speech warning against 'Grammar of Anarchy' and 'Bhakti in politics'\n4. Dr. Rajendra Prasad delivers his valedictory address as President of the Constituent Assembly",
    "அரசியலமைப்பு அவையில் ஆற்றப்பட்ட பின்வரும் வரலாற்றுச் சிறப்புமிக்க உரைகளை சரியான காலவரிசையில் அமைக்கவும்:\n1. சுதந்திர இறையாண்மை கொண்ட குடியரசைக் கோரும் குறிக்கோள்கள் தீர்மானத்தை ஜவகர்லால் நேரு முன்மொழிதல்\n2. அம்பேத்கர் அரசியலமைப்பின் முதல் வரைவை அறிமுகப்படுத்துதல்\n3. 'அராஜகத்தின் இலக்கணம்' மற்றும் 'அரசியலில் பக்தி'க்கு எதிராக அம்பேத்கர் எச்சரிக்கை உரை ஆற்றுதல்\n4. அரசியலமைப்பு அவையின் தலைவராக டாக்டர் ராஜேந்திர பிரசாத் நிறைவுரை ஆற்றுதல்",
    ["Jawaharlal Nehru moves Objectives Resolution calling for an Independent Sovereign Republic", "Dr. B.R. Ambedkar introduces the First Draft of the Constitution", "Dr. B.R. Ambedkar delivers his speech warning against 'Grammar of Anarchy' and 'Bhakti in politics'", "Dr. Rajendra Prasad delivers his valedictory address as President of the Constituent Assembly"],
    ["சுதந்திர இறையாண்மை கொண்ட குடியரசைக் கோரும் குறிக்கோள்கள் தீர்மானத்தை ஜவகர்லால் நேரு முன்மொழிதல்", "அம்பேத்கர் அரசியலமைப்பின் முதல் வரைவை அறிமுகப்படுத்துதல்", "'அராஜகத்தின் இலக்கணம்' மற்றும் 'அரசியலில் பக்தி'க்கு எதிராக அம்பேத்கர் எச்சரிக்கை உரை ஆற்றுதல்", "அரசியலமைப்பு அவையின் தலைவராக டாக்டர் ராஜேந்திர பிரசாத் நிறைவுரை ஆற்றுதல்"],
    "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "1 -> 3 -> 2 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Nehru speech, Dec 13, 1946) -> 2 (Ambedkar draft intro, Nov 4, 1948) -> 3 (Ambedkar final speech, Nov 25, 1949) -> 4 (Rajendra Prasad closing address, Nov 26, 1949).",
    "சரியான காலவரிசை: 1 (நேரு உரை, டிச 13, 1946) -> 2 (அம்பேத்கர் வரைவு அறிமுக உரை, நவ 4, 1948) -> 3 (அம்பேத்கர் இறுதி எச்சரிக்கை உரை, நவ 25, 1949) -> 4 (ராஜேந்திர பிரசாத் நிறைவுரை, நவ 26, 1949).",
    "Correct. 1 (Dec 13, 1946) -> 2 (Nov 4, 1948) -> 3 (Nov 25, 1949) -> 4 (Nov 26, 1949) is exact.", "சரி. 1 (டிச 13, 1946) -> 2 (நவ 4, 1948) -> 3 (நவ 25, 1949) -> 4 (நவ 26, 1949) துல்லியமானது.",
    "Incorrect. Nehru's speech (Dec 1946) was earlier than Ambedkar's draft introduction (Nov 1948).", "தவறு. நேருவின் உரை (டிச 1946) அம்பேத்கரின் வரைவு அறிமுகத்திற்கு முந்தியது.",
    "Incorrect. Ambedkar introduced draft (Nov 1948) before his final speech (Nov 25, 1949).", "தவறு. அம்பேத்கர் வரைவை அறிமுகப்படுத்தியது (நவ 1948) அவரது இறுதி உரைக்கு முந்தியது.",
    "Incorrect. Nehru's speech (Dec 1946) was the earliest speech among these.", "தவறு. நேருவின் உரை (டிச 1946) மிக முந்தையது.",
    "TNPSC Trap: Ambedkar's famous 'Grammar of Anarchy' speech was delivered on Nov 25, 1949, one day BEFORE final adoption on Nov 26, 1949.",
    "TNPSC பொறி: அம்பேத்கரின் புகழ்பெற்ற 'அராஜகத்தின் இலக்கணம்' உரை நவம்பர் 26, 1949 இறுதி ஏற்பிற்கு ஒரு நாள் முன்பு (நவம்பர் 25, 1949) ஆற்றப்பட்டது.",
    "Dr. Rajendra Prasad praised Ambedkar's chairmanship, noting no choice could have been more solemn.",
    "டாக்டர் ராஜேந்திர பிரசாத் அம்பேத்கரின் தலைமையைப் பாராட்டி உரை நிகழ்த்தினார்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "Objectives Resolution", "Ambedkar's Final Speech", "Grammar of Anarchy"]
))

# MIC_CHRONO_017
questions.append(make_chrono_q(
    "MIC_CHRONO_017", "Chronology",
    "Which of the following represents the correct chronological order of contributions by Constitutional Adviser Sir B.N. Rau?\n1. Appointment as Constitutional Adviser to the Constituent Assembly\n2. Tour of USA, UK, Canada, and Ireland to consult leading legal experts\n3. Preparation of the preliminary Draft Constitution containing 243 Articles\n4. Recommending replacement of 'due process of law' with 'procedure established by law'",
    "அரசியலமைப்பு ஆலோசகர் சர் பி.என். ராவின் பங்களிப்புகளின் சரியான காலவரிசை எது?\n1. அரசியலமைப்பு அவையின் அரசியலமைப்பு ஆலோசகராக நியமிக்கப்படுதல்\n2. சட்ட நிபுணர்களைக் கலந்தாலோசிக்க அமெரிக்கா, இங்கிலாந்து, கனடா, அயர்லாந்து நாடுகளுக்குப் பயணம் செய்தல்\n3. 243 சரத்துகளைக் கொண்ட ஆரம்ப வரைவு அரசியலமைப்பைத் தயாரித்தல்\n4. 'சட்டத்தின் உரிய நடைமுறை' என்பதை 'சட்டத்தால் அமைக்கப்பட்ட நடைமுறை'யால் மாற்றப் பரிந்துரைத்தல்",
    ["Appointment as Constitutional Adviser to the Constituent Assembly", "Tour of USA, UK, Canada, and Ireland to consult leading legal experts", "Preparation of the preliminary Draft Constitution containing 243 Articles", "Recommending replacement of 'due process of law' with 'procedure established by law'"],
    ["அரசியலமைப்பு அவையின் அரசியலமைப்பு ஆலோசகராக நியமிக்கப்படுதல்", "சட்ட நிபுணர்களைக் கலந்தாலோசிக்க அமெரிக்கா, இங்கிலாந்து, கனடா, அயர்லாந்து நாடுகளுக்குப் பயணம் செய்தல்", "243 சரத்துகளைக் கொண்ட ஆரம்ப வரைவு அரசியலமைப்பைத் தயாரித்தல்", "‘சட்டத்தின் உரிய நடைமுறை’ என்பதை ‘சட்டத்தால் அமைக்கப்பட்ட நடைமுறை’யால் மாற்றப் பரிந்துரைத்தல்"],
    "1 -> 3 -> 2 -> 4", "1 -> 2 -> 3 -> 4", "2 -> 1 -> 3 -> 4", "3 -> 1 -> 2 -> 4",
    "A",
    "Correct Chronological Sequence: 1 (Appointment, July 1946) -> 3 (Prepared 243-Article Draft, Oct 1947) -> 2 (Foreign study tour, Oct-Nov 1947) -> 4 (Advice on due process following Felix Frankfurter meeting, late 1947/early 1948).",
    "சரியான காலவரிசை: 1 (நியமனம், ஜூலை 1946) -> 3 (243 சரத்து வரைவு தயாரிப்பு, அக்டோபர் 1947) -> 2 (வெளிநாட்டுப் பயணம், அக்டோபர்-நவம்பர் 1947) -> 4 (சட்ட நடைமுறை மாற்ற ஆலோசனை, 1947 இறுதி/1948 தொடக்கம்).",
    "Correct. 1 (July 1946) -> 3 (Oct 1947) -> 2 (Oct-Nov 1947) -> 4 (Late 1947) is exact.", "சரி. 1 (ஜூலை 1946) -> 3 (அக்டோபர் 1947) -> 2 (அக்டோபர்-நவம்பர் 1947) -> 4 (1947 இறுதி) துல்லியமானது.",
    "Incorrect. B.N. Rau prepared the initial draft (3) before undertaking his foreign tour (2).", "தவறு. பி.என். ராவ் ஆரம்ப வரைவை (3) வெளிநாட்டுப் பயணத்திற்கு (2) முன்பே தயாரித்தார்.",
    "Incorrect. B.N. Rau was appointed in July 1946 (1), before his foreign tour in Oct 1947 (2).", "தவறு. பி.என். ராவ் ஜூலை 1946 இல் நியமிக்கப்பட்டார் (1).",
    "Incorrect. B.N. Rau was appointed in July 1946 (1), before preparing draft in Oct 1947 (3).", "தவறு. பி.என். ராவ் ஜூலை 1946 இல் நியமிக்கப்பட்டார் (1).",
    "TNPSC Trap: Sir B.N. Rau prepared his initial draft in Oct 1947 BEFORE going on his foreign study tour to USA, UK, Canada, and Ireland.",
    "TNPSC பொறி: சர் பி.என். ராவ் அமெரிக்கா, இங்கிலாந்து, கனடா, அயர்லாந்து வெளிநாட்டுப் பயணத்திற்குச் செல்லும் முன்பே அக்டோபர் 1947 இல் தனது முதல் வரைவைத் தயாரித்தார்.",
    "Sir B.N. Rau later served as India's representative at the UN Security Council and Judge of the International Court of Justice (ICJ).",
    "சர் பி.என். ராவ் பின்னர் ஐ.நா பாதுகாப்பு கவுன்சிலில் இந்தியாவின் பிரதிநிதியாகவும் சர்வதேச நீதிமன்ற நீதிபதியாகவும் பணியாற்றினார்.",
    "Analyze", 75, ["Polity", "Making of Indian Constitution", "B. N. Rau", "Constitutional Adviser", "Draft Constitution"]
))
